func (t Event) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t Event) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "agent.delivery_changed":
		return t.AsAgentDeliveryChangedEvent()
	case "agent.left":
		return t.AsAgentLeftEvent()
	case "agent.removed":
		return t.AsAgentRemovedEvent()
	case "board.archived":
		return t.AsBoardArchivedEvent()
	case "board.created":
		return t.AsBoardCreatedEvent()
	case "board.deleted":
		return t.AsBoardDeletedEvent()
	case "board.policy_changed":
		return t.AsBoardPolicyChangedEvent()
	case "board.restored":
		return t.AsBoardRestoredEvent()
	case "board.titled":
		return t.AsBoardTitledEvent()
	case "board.visibility_changed":
		return t.AsBoardVisibilityChangedEvent()
	case "joincode.created":
		return t.AsJoinCodeCreatedEvent()
	case "joincode.revoked":
		return t.AsJoinCodeRevokedEvent()
	case "member.joined":
		return t.AsMemberJoinedEvent()
	case "message.posted":
		return t.AsMessagePostedEvent()
	case "person.added":
		return t.AsPersonAddedEvent()
	case "person.left":
		return t.AsPersonLeftEvent()
	case "person.made_owner":
		return t.AsPersonMadeOwnerEvent()
	case "person.removed":
		return t.AsPersonRemovedEvent()
	case "reaction.added":
		return t.AsReactionAddedEvent()
	case "reaction.removed":
		return t.AsReactionRemovedEvent()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

